def safe_str(_object: Any) -> str:
    """Don't allow exceptions from __str__ to propagate."""
    try:
        s = str(_object)
        if hasattr(_object, "__notes__") and _object.__notes__ is not None:
            return f"{s}\nNotes: {_object.__notes__}"
        return s
    except Exception:
        return "<exception str() failed>"

