python3 - <<'PY'
from rich.traceback import Traceback
import sys
from typing import Optional

class MyException(Exception):
    def __init__(self, message: str, notes: Optional[str] = None):
        super().__init__(message)
        self.__notes__ = notes

def test_exception_with_notes():
    print("--- Testing Exception with Notes ---")
    try:
        raise MyException("Error message", notes="This is a critical note.")
    except MyException as e:
        tb = Traceback(e)
        print("Traceback output (should contain notes):")
        print(tb)

def test_exception_without_notes():
    print("\n--- Testing Exception without Notes ---")
    try:
        raise MyException("Simple error")
    except MyException as e:
        tb = Traceback(e)
        print("Traceback output (should NOT contain notes):")
        print(tb)

def test_exception_with_none_notes():
    print("\n--- Testing Exception with None Notes ---")
    try:
        raise MyException("Error with None notes", notes=None)
    except MyException as e:
        tb = Traceback(e)
        print("Traceback output (should NOT contain notes):")
        print(tb)

if __name__ == "__main__":
    test_exception_with_notes()
    test_exception_without_notes()
    test_exception_with_none_notes()
